import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import { BrowserRouter } from 'react-router-dom'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { App } from './App'
import { applyStoredTheme } from './hooks/useTheme'
import { applyStoredAppearance } from './hooks/useDensity'
import { applyStoredLanguage } from './i18n/state.ts'
import { LanguageProvider } from './i18n/language.tsx'
import { setLocale } from './lib/locale.ts'
import { installCsrf } from './lib/csrf.ts'
// Generated by docs/build_fonts.py from the Python project's woff2 files.
// Imported before tokens.css so the font faces are registered before anything
// asks for the family.
import './styles/fonts.generated.css'
import './styles/fonts-latin.css'
// Geist, for the landing page only. Its own file so the app's Manrope face and
// the generated Vazirmatn faces stay untouched (see fonts-landing.css).
import './styles/fonts-landing.css'
// The ink/emerald roles for the public surfaces (landing + auth). Declared
// before tokens.css so the custom properties exist before anything reads them.
import './styles/ink.css'
import './styles/tokens.css'
import './styles/ui.css'

// Must run before the first paint, otherwise a dark-mode user sees a white
// flash while React boots -- and an English user sees an RTL flash.
applyStoredTheme()
applyStoredAppearance()
setLocale(applyStoredLanguage())

// Cookie-authenticated writes must echo the CSRF cookie in a header (Phase 1).
// Installed once, before any request, so no call site can forget it.
installCsrf()

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      retry: 1,
      // The backend is a local process; failing fast beats a long spinner.
      refetchOnWindowFocus: true,
      staleTime: 1000,
    },
  },
})

const container = document.getElementById('root')
if (!container) throw new Error('Root container #root is missing from index.html')

createRoot(container).render(
  <StrictMode>
    <QueryClientProvider client={queryClient}>
      <BrowserRouter>
        <LanguageProvider>
          <App />
        </LanguageProvider>
      </BrowserRouter>
    </QueryClientProvider>
  </StrictMode>,
)
